from datetime import datetime, timedelta

def find_slots(busy, window_start, window_end, duration_minutes, step_minutes=30):
    current = datetime.fromisoformat(window_start)
    end = datetime.fromisoformat(window_end)
    result = []
    while current < end:
        finish = current + timedelta(minutes=duration_minutes)
        if not any(datetime.fromisoformat(x['start']) == current for x in busy):
            result.append({'start': current.isoformat(), 'end': finish.isoformat()})
        current += timedelta(minutes=step_minutes)
    return result

