from datetime import datetime, timezone

def _timestamp(value):
    if not isinstance(value, str):
        raise ValueError('timestamp must be a string')
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as error:
        raise ValueError('invalid timestamp') from error
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError('timezone required')
    return parsed.astimezone(timezone.utc)

def summarize_events(events, since=None, until=None):
    start = _timestamp(since) if since is not None else None
    end = _timestamp(until) if until is not None else None
    if start is not None and end is not None and start >= end:
        raise ValueError('invalid window')
    if not isinstance(events, list):
        raise ValueError('events must be a list')
    selected = []
    for event in events:
        if not isinstance(event, dict):
            raise ValueError('event must be a mapping')
        user, action = event.get('user'), event.get('action')
        if not isinstance(user, str) or not user.strip():
            raise ValueError('user required')
        if not isinstance(action, str) or not action.strip():
            raise ValueError('action required')
        if type(event.get('success')) is not bool:
            raise ValueError('success must be a boolean')
        timestamp = _timestamp(event.get('timestamp'))
        if (start is None or timestamp >= start) and (end is None or timestamp < end):
            selected.append((user.strip(), action.strip(), event['success']))
    users = {}
    for user, action, success in selected:
        row = users.setdefault(user, {'total': 0, 'successful': 0, 'failed': 0})
        row['total'] += 1
        row['successful' if success else 'failed'] += 1
    successful = sum(success for user, action, success in selected)
    return {'total': len(selected), 'successful': successful,
            'failed': len(selected) - successful, 'by_user': users,
            'actions': sorted({action for user, action, success in selected})}

