from datetime import datetime, timedelta, timezone

def _timestamp(value):
    if not isinstance(value, str):
        raise ValueError('timestamp must be a string')
    try:
        result = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError as error:
        raise ValueError('invalid timestamp') from error
    if result.tzinfo is None or result.utcoffset() is None:
        raise ValueError('timezone required')
    return result.astimezone(timezone.utc)

def find_slots(busy, window_start, window_end, duration_minutes, step_minutes=30):
    start, end = _timestamp(window_start), _timestamp(window_end)
    if start >= end:
        raise ValueError('invalid window')
    if type(duration_minutes) is not int or duration_minutes <= 0:
        raise ValueError('invalid duration')
    if type(step_minutes) is not int or step_minutes <= 0:
        raise ValueError('invalid step')
    if not isinstance(busy, list):
        raise ValueError('busy must be a list')
    intervals = []
    for item in busy:
        if not isinstance(item, dict):
            raise ValueError('interval must be a mapping')
        a, b = _timestamp(item.get('start')), _timestamp(item.get('end'))
        if a >= b:
            raise ValueError('invalid interval')
        intervals.append((a, b))
    result = []
    current = start
    duration, step = timedelta(minutes=duration_minutes), timedelta(minutes=step_minutes)
    while current + duration <= end:
        finish = current + duration
        if not any(current < b and finish > a for a, b in intervals):
            result.append({'start': current.isoformat(), 'end': finish.isoformat()})
        current += step
    return result

