from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from money import parse_money

def price_lines(items, discount_percent='0'):
    if isinstance(discount_percent, bool) or not isinstance(discount_percent, (str, int, Decimal)):
        raise ValueError('invalid discount')
    try:
        percent = Decimal(discount_percent)
    except InvalidOperation as error:
        raise ValueError('invalid discount') from error
    if not percent.is_finite() or not 0 <= percent <= 100:
        raise ValueError('invalid discount')
    if not isinstance(items, list):
        raise ValueError('items must be a list')
    result = []
    for item in items:
        if not isinstance(item, dict):
            raise ValueError('invalid item')
        sku, quantity = item.get('sku'), item.get('quantity')
        if not isinstance(sku, str) or not sku.strip():
            raise ValueError('invalid sku')
        if type(quantity) is not int or quantity <= 0:
            raise ValueError('invalid quantity')
        subtotal = parse_money(item.get('unit_price')) * quantity
        total = (subtotal * (1 - percent / 100)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
        result.append({'sku': sku.strip(), 'quantity': quantity, 'subtotal': subtotal, 'total': total})
    return result
